import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class RolepermitService {


  roles = {
    1: '8632ee5c-e854-411c-b83d-c21656ad39ac', // 2
    2: 'acbac68b-0921-457d-8a6a-543197cfa312', // 3
    3: 'b1316999-8cc8-44e1-973c-04febcdc782b', // 4
    4: 'e286a210-e979-4491-a537-c8021976f657', // 5
    5: 'dd234aaf-82bb-475c-a5e4-777f6a347039' // 6
  }


  private _userPermission$ = new BehaviorSubject<any[]>([]);
  readonly userPermission$: Observable<any[]> = this._userPermission$.asObservable();

  permissionCaseid: string;
  constructor() { }


  isAdmin(roleid) {
    return !roleid ? false : roleid == this.roles["1"]; // 2
  }

  isPresenter(roleid) {
    return !roleid ? false : roleid == this.roles[5];
  }

  isCanPresent(roleid, jPermission: string[]) {
    return !roleid ? false : (roleid != this.roles["3"] && roleid != this.roles["4"]) && !jPermission?.includes('PT'); // 4 , 5
  }


  isHaveRealtime(jPermission: string[]) {
    return !(jPermission?.includes('RT'));
  }

  isHaveView(jPermission: string[]) {
    return !(jPermission?.includes('VC'));
  }


  setUserPermissionArray(value: any[]) {
    this._userPermission$.next(value);
  }

  isUserHavePermission(jPermission: string[], type: string) {
    return !(jPermission?.includes(type));
  }

  verifyPermission(type: string) {
    const value = this._userPermission$.getValue() || [];
    return !value.includes(type);
  }

}
